controls.read:
({ req })=>{
    if (!req.user) {
        return false;
    }
    const userValueCondition = {
        'user.value': {
            equals: req.user.id
        }
    };
    const userRelationCondition = {
        'user.relationTo': {
            equals: req.user.collection
        }
    };
    return {
        and: [
            userValueCondition,
            userRelationCondition
        ]
    };
}

